#!/usr/bin/env python3
"""
Round 111c (tiles), 29 September 2026. scripts/capture.py: more secret-police
Wikipedias, development banks' debarments, FARA, and capture/by_country.json.
Whole file, written only if it differs.
"""
import base64, pathlib

FILES = {'scripts/capture.py': ''}


def main():
    for p, b in FILES.items():
        data = base64.b64decode(b)
        f = pathlib.Path(p)
        if f.exists() and f.read_bytes() == data:
            print(f"round111c: {p} already up to date")
            continue
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_bytes(data)
        print(f"round111c: wrote {p}")


if __name__ == "__main__":
    main()
